// ---------------------------------------------------------------------------
// 换聊天守卫
// ---------------------------------------------------------------------------

/**
 * ⚠️⚠️ 推演是**异步**的（要等模型几秒到几十秒），而 `state()` 每次都去读
 *   **"当前这个聊天"** 的 chat_metadata ⇒ 中途换了聊天，这一次推演的结果就会
 *   写进**另一个聊天**（整份状态被覆盖 + 追加一条错快照）✗。
 *
 * 原来的防护只有一个 `onChatChanged` 里的 `clearPending()` ——
 *   那只清"还在排队、还没发出去"的那次，**已经发出去的请求照样会回来** ✗。
 *
 * ⇒ 判据：开跑时记一份"这一次是给哪个聊天算的"（`getChatKey()`），
 *   凡是**要落盘/改状态**的地方先比一次；一变就直接放弃，一个字都不写 ✓。
 *   这是**第二道**防线（第一道在 index.js 的 onChatChanged：换聊天就把这次请求掐断 ✓）。
 */
function chatKeyNow() {
    try { return getChatKey(); } catch { return ''; }
}

// ★ 受精判定那一轮就把「胎位」掷满
//   子1 到子4，每一胎各自从候选池里独立掷一次（真骰子，骰子页签上看得到）。
//   为什么不在胎数判出来之后再补掷：受精成功却**着床失败**时，补掷永远不会发生
//   ⇒ 骰子页签上缺一半、看起来很怪 ✗（要的是一次掷完）
//   ⚠️ 5 胎以上归模块里的「分批归属」（几十上百枚不可能逐枚掷）
const IMPREGNATOR_SLOTS = 4;

