// ⚠️ 契约是**真发给 AI 的文本**（buildContract() 只删可选字段行，不剥注释）⇒ 模板字符串里：
//   · 不许出现「插件」二字（要指代执行方就用「系统」）
//   · 不许 markdown 加粗（`**`）
//   · 不许描述性破折号（`——`）
//   · 不许留 `//` 注释（模型会照着写）
//   这四条同样适用于契约模板（自测脚本 有断言盯着 ✓）
//   ⚠️ 想写"为什么这么改"这种给开发者看的话，就写在这行注释里，**别写进模板** ✗
//   ★ `Is_Pregnant` 那一格不在契约里 —— 它由插件自己掌握
//     （起点 = 着床完成日到点，见 store.js 的 `syncPregnancyState`；终点 = 分娩 / 妊娠终止事件）。
//     AI 只在【上一轮状态】的 vars 里读它 ⇒ **别再往契约里加回来** ✗
